import fs from 'fs';
import os from 'os';
import path from 'path';
import type { CallerAgentKind, CallerHandoff } from './handoff';

type CallerSessionEnvironment = {
  env?: NodeJS.ProcessEnv;
  homeDir?: string;
};

type CallerSessionWait = CallerSessionEnvironment & { waitMs?: number };

type SessionLogEntry = {
  type?: unknown;
  isSidechain?: unknown;
  message?: { model?: unknown };
  payload?: { model?: unknown };
};

type CallerSessionLog = {
  filePath: () => string | undefined;
  modelOf: (entry: SessionLogEntry) => string | undefined;
};

const SESSION_LOG_TAIL_BYTES = 4 * 1024 * 1024;
const SESSION_MODEL_WAIT_MS = 1500;
const SESSION_MODEL_POLL_INTERVAL_MS = 100;
const CLAUDE_SYNTHETIC_MODEL = '<synthetic>';
const CODEX_TURN_METADATA_KEY = 'x-codex-turn-metadata';

const nonEmptyString = (value: unknown): string | undefined =>
  typeof value === 'string' && value.trim() ? value.trim() : undefined;

const readDirectory = (directory: string): string[] => {
  try {
    return fs.readdirSync(directory);
  } catch {
    return [];
  }
};

const readTailLines = (filePath: string): string[] => {
  const handle = fs.openSync(filePath, 'r');
  try {
    const { size } = fs.fstatSync(handle);
    const length = Math.min(size, SESSION_LOG_TAIL_BYTES);
    const buffer = Buffer.alloc(length);
    fs.readSync(handle, buffer, 0, length, size - length);
    const lines = buffer.toString('utf8').split('\n');
    return length < size ? lines.slice(1) : lines;
  } finally {
    fs.closeSync(handle);
  }
};

const latestModelIn = (
  filePath: string,
  modelOf: CallerSessionLog['modelOf'],
): string | undefined => {
  const lines = readTailLines(filePath);
  for (let index = lines.length - 1; index >= 0; index--) {
    let entry: SessionLogEntry;
    try {
      entry = JSON.parse(lines[index]) as SessionLogEntry;
    } catch {
      continue;
    }
    const model =
      entry && typeof entry === 'object' ? modelOf(entry) : undefined;
    if (model) return model;
  }
  return undefined;
};

const claudeSessionLog = (
  sessionId: string,
  { env = process.env, homeDir = os.homedir() }: CallerSessionEnvironment,
): CallerSessionLog => ({
  filePath: () => {
    const projectsDir = path.join(
      env.CLAUDE_CONFIG_DIR ?? path.join(homeDir, '.claude'),
      'projects',
    );
    return readDirectory(projectsDir)
      .map((project) => path.join(projectsDir, project, `${sessionId}.jsonl`))
      .find((candidate) => fs.existsSync(candidate));
  },
  modelOf: (entry) => {
    if (entry.type !== 'assistant' || entry.isSidechain === true) {
      return undefined;
    }
    const model = nonEmptyString(entry.message?.model);
    return model === CLAUDE_SYNTHETIC_MODEL ? undefined : model;
  },
});

const newestFirst = (directory: string): string[] =>
  readDirectory(directory).sort().reverse();

const codexSessionLog = (
  threadId: string,
  { env = process.env, homeDir = os.homedir() }: CallerSessionEnvironment,
): CallerSessionLog => ({
  filePath: () => {
    const sessionsDir = path.join(
      env.CODEX_HOME ?? path.join(homeDir, '.codex'),
      'sessions',
    );
    const rolloutSuffix = `-${threadId}.jsonl`;
    for (const year of newestFirst(sessionsDir)) {
      for (const month of newestFirst(path.join(sessionsDir, year))) {
        for (const day of newestFirst(path.join(sessionsDir, year, month))) {
          const dayDir = path.join(sessionsDir, year, month, day);
          const rollout = readDirectory(dayDir).find(
            (name) =>
              name.startsWith('rollout-') && name.endsWith(rolloutSuffix),
          );
          if (rollout) return path.join(dayDir, rollout);
        }
      }
    }
    return undefined;
  },
  modelOf: (entry) =>
    entry.type === 'turn_context'
      ? nonEmptyString(entry.payload?.model)
      : undefined,
});

const callerSessionLogFor = (
  agent: CallerAgentKind,
  environment: CallerSessionEnvironment,
): CallerSessionLog | undefined => {
  const env = environment.env ?? process.env;
  if (agent === 'claude') {
    const sessionId = nonEmptyString(env.CLAUDE_CODE_SESSION_ID);
    return sessionId ? claudeSessionLog(sessionId, environment) : undefined;
  }
  if (agent === 'codex') {
    const threadId = nonEmptyString(env.CODEX_THREAD_ID);
    return threadId ? codexSessionLog(threadId, environment) : undefined;
  }
  return undefined;
};

const modelFromSessionLog = (log: CallerSessionLog): string | undefined => {
  try {
    const filePath = log.filePath();
    return filePath ? latestModelIn(filePath, log.modelOf) : undefined;
  } catch {
    return undefined;
  }
};

export const readCallerSessionModel = (
  agent: CallerAgentKind,
  environment: CallerSessionEnvironment = {},
): string | undefined => {
  const log = callerSessionLogFor(agent, environment);
  return log ? modelFromSessionLog(log) : undefined;
};

const sleep = (delayMs: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, delayMs));

export const withCallerSessionModel = async (
  handoff: CallerHandoff | null,
  environment: CallerSessionWait = {},
): Promise<CallerHandoff | null> => {
  if (!handoff) return handoff;
  const log = callerSessionLogFor(handoff.agent, environment);
  if (!log) return handoff;
  const deadline = Date.now() + (environment.waitMs ?? SESSION_MODEL_WAIT_MS);
  for (;;) {
    const model = modelFromSessionLog(log);
    if (model) return { ...handoff, model };
    if (Date.now() >= deadline) return handoff;
    await sleep(SESSION_MODEL_POLL_INTERVAL_MS);
  }
};

export const callerModelArgsFromToolMeta = (meta: unknown): string[] => {
  if (typeof meta !== 'object' || meta === null) return [];
  const turn = (meta as Record<string, unknown>)[CODEX_TURN_METADATA_KEY];
  const model =
    typeof turn === 'object' && turn !== null
      ? nonEmptyString((turn as Record<string, unknown>).model)
      : undefined;
  return model ? ['--caller-model', model] : [];
};
